    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'Which of the following describes "Physician-Assisted Suicide" (PAS), also known as Physician-Assisted Death (PAD)?', '["The doctor injects a lethal drug", "The doctor provides the means (e.g., a prescription for lethal medication) for the patient to self-administer at a time of their choosing", "The doctor turns off the ventilator", "None of the above"]', 1, 'In PAS, the final act of administration is performed by the patient, distinguishing it from euthanasia.'),
    (v_topic_id, 'In which of the following US states was the first "Death with Dignity Act" passed in 1994?', '["California", "Oregon", "Washington", "Vermont"]', 1, 'Oregon was the pioneer in legalizing physician-assisted suicide in the United States.'),
    (v_topic_id, 'Which of the following is a "Legal Requirement" for a patient to request PAS in jurisdictions where it is legal?', '["The patient must be under 50", "The patient must be competent and have a terminal illness with a prognosis of 6 months or less", "The patient must have no family", "None of the above"]', 1, 'Strict safeguards ensure that PAS is only an option for competent terminal patients.'),
    (v_topic_id, 'What is the "Supreme Court''s" current stance on the "Right to PAS" based on the cases of Glucksberg and Quill?', '["PAS is a constitutional right for everyone", "There is no federal constitutional right to PAS; states are free to ban it or legalize it as they see fit", "PAS is illegal everywhere in the US", "None of the above"]', 1, 'The court ruled that while there is no constitutional "right to die" via assisted suicide, the states have the authority to decide for themselves.'),
    (v_topic_id, 'The "Uniform Determination of Death Act" (UDDA) defines death as either irreversible cessation of circulatory and respiratory functions OR:', '["Loss of all memory", "Irreversible cessation of all functions of the entire brain, including the brainstem", "Being in a coma for 1 year", "None of the above"]', 1, 'This is the dual-criteria definition of death used in almost all US jurisdictions.'),
    (v_topic_id, 'Which of the following is a clinical test for "Brain Death"?', '["A blood test", "The Apnea Test (demonstrating no respiratory drive despite rising CO2 levels)", "A skin biopsy", "None of the above"]', 1, 'The apnea test is a critical component of the brain death examination.'),
    (v_topic_id, 'In the "SPIKES" protocol, what does the "P" stand for?', '["Patient", "Perception (Finding out what the patient already knows or suspects)", "Prognosis", "Pain"]', 1, 'Understanding the patient''s baseline knowledge helps the clinician bridge the gap to the new information.'),
    (v_topic_id, 'The "Cruzan" case established that a state can require "Clear and Convincing Evidence" of a patient''s wishes. What does this mean for clinical practice?', '["Oral statements are enough", "Written advance directives are the strongest way to ensure a patient''s wishes are followed if they become incapacitated", "Doctors should ignore evidence", "None of the above"]', 1, 'The case highlighted the importance of formal advance planning.'),
    (v_topic_id, 'What is "Donation after Circulatory Death" (DCD)?', '["Donating money", "Organ procurement from a patient whose death is declared after the irreversible cessation of heart and lung function (often following withdrawal of life support)", "Donating blood", "None of the above"]', 1, 'DCD is an alternative to "Brain Death" donation and allows more families the opportunity for organ donation.'),
    (v_topic_id, 'Which of the following is a "Conscientious Objection" for a physician?', '["Refusing to work on Mondays", "Refusing to participate in PAS or withdrawal of care for personal moral or religious reasons, while ensuring the patient is not abandoned and care is transferred", "Refusing to see a specific race of patient", "None of the above"]', 1, 'Physicians have the right to their own moral integrity, provided it does not harm the patient.'),
    (v_topic_id, 'In the "SPIKES" protocol, the "I" (Invitation) refers to:', '["Inviting the family to dinner", "Asking the patient how much information they want to receive (e.g., "Would you like me to give you the details or just the big picture?")", "Inviting another doctor into the room", "None of the above"]', 1, 'The invitation respects the patient''s autonomy regarding the depth of disclosure.'),
    (v_topic_id, 'The "Vacco v. Quill" case established a legal distinction between:', '["Killing and letting die", "The intent of a doctor providing high-dose opioids for pain vs. the intent of a doctor providing a lethal prescription", "Medicare and Medicaid", "None of the above"]', 1, 'The court affirmed that providing comfort care is NOT the same as providing assisted suicide.'),
    (v_topic_id, 'Which of the following is NOT a step in declaring brain death?', '["Confirming irreversible cause of coma", "Confirming absence of brainstem reflexes (e.g., gag, corneal)", "Checking for a pulse", "Performing a "brain dead" ritual"]', 3, 'Brain death is a strictly medical/legal determination.'),
    (v_topic_id, 'What is "Medical Paternalism"?', '["A father who is a doctor", "The practice of making decisions for a patient without their consent, based on the belief that the doctor knows what is best", "A type of insurance", "None of the above"]', 1, 'Modern medical ethics has largely moved away from paternalism toward autonomy and shared decision-making.'),
    (v_topic_id, 'The "Quinlan" case (1976) was the first major case to recognize:', '["The right to abortion", "The right of a family to request the withdrawal of a ventilator from a patient in a persistent vegetative state", "The right to free healthcare", "None of the above"]', 1, 'The Quinlan case laid the foundation for "Right to Die" jurisprudence in the US.'),
    (v_topic_id, 'In "Organ Donation" discussions, what is the "Dead Donor Rule"?', '["Only dead people can donate", "The ethical requirement that organ procurement must not be the cause of the donor''s death", "You must be dead for 1 year", "None of the above"]', 1, 'The Dead Donor Rule ensures that organ donation is a post-mortem act (in the context of vital organs).'),
    (v_topic_id, 'Which of the following is a "Strategy" (the S in SPIKES) after giving bad news?', '["Leaving the room immediately", "Developing a plan for the next steps and ensuring the patient/family has a way to contact the team", "Telling the patient everything will be fine", "None of the above"]', 1, 'Ending with a concrete plan reduces the sense of helplessness.'),
    (v_topic_id, 'What is the "Self-Administered" requirement in PAS?', '["The doctor must watch the patient", "The patient must be physically and mentally capable of taking the medication themselves", "The patient must buy the meds", "None of the above"]', 1, 'This is a key legal safeguard in US PAS laws.'),
    (v_topic_id, 'A patient is "Brain Dead" and their family wants to keep them on a ventilator to "wait for a miracle." What is the best approach?', '["Turn the ventilator off immediately", "Use a multi-disciplinary approach (ethics, chaplain, social work) to provide support and education while explaining that the patient is legally dead, though some jurisdictions/hospitals allow a short delay", "Keep the ventilator on forever", "None of the above"]', 1, 'This is one of the most difficult conflicts in hospital ethics.'),
    (v_topic_id, 'Which of the following "Protects" the physician when breaking bad news?', '["Being blunt and fast", "Empathetic communication, clear language, and a structured approach (like SPIKES)", "Hiding the truth", "None of the above"]', 1, 'Good communication is the best defense against patient/family distress and legal risk.'),
    (v_topic_id, 'The "Glucksberg" case (1997) involved a challenge to a state law banning:', '["Abortion", "Assisted Suicide", "Smoking", "None of the above"]', 1, 'Washington v. Glucksberg is a landmark case regarding the "liberty interest" in dying.'),
    (v_topic_id, 'What is "Active Euthanasia"?', '["Assisting a suicide", "The direct administration of a lethal substance by a physician with the intent to cause death", "Withdrawing a ventilator", "None of the above"]', 1, 'Active euthanasia is illegal in the US.'),
    (v_topic_id, 'Which of the following is a "Non-verbal" communication technique for breaking bad news?', '["Sitting down at the patient''s level", "Maintaining appropriate eye contact", "Using silence to allow the patient to process", "All of the above"]', 3, 'Non-verbal cues are just as important as words in SPIKES.'),
    (v_topic_id, 'In the context of "Death with Dignity" laws, what is the "Wait Period"?', '["Waiting for a bed", "A mandatory time (e.g., 15 days) between the first and second oral request for PAS to ensure the request is stable and voluntary", "Waiting for the bill", "None of the above"]', 1, 'The wait period is a safeguard against impulsive decisions.'),
    (v_topic_id, 'Which of the following describes "Passive Euthanasia"?', '["A term sometimes used to describe the withdrawal or withholding of life-sustaining treatment (though "allowing to die" is the preferred term)", "Giving a lethal injection", "Killing a patient in their sleep", "None of the above"]', 0, 'The term "passive euthanasia" is generally discouraged because it conflates killing with allowing the disease to take its course.'),
    (v_topic_id, 'The "Best Interest" standard for an incapacitated patient is based on:', '["What the patient would have wanted", "What a "reasonable person" would choose in the same situation, focusing on relief of suffering and quality of life", "What the doctor wants", "None of the above"]', 1, 'Best interest is the "objective" standard used when subjective data is missing.'),
    (v_topic_id, 'Which of the following is TRUE regarding "Organ Donation" and PAS?', '["It is mandatory", "There is ongoing ethical debate about whether patients choosing PAS should be eligible for organ donation (e.g., in some European countries this occurs, but it is rare/not established in the US)", "It is illegal", "None of the above"]', 1, 'This is a complex and evolving ethical area.'),
    (v_topic_id, 'What is the "E" in SPIKES?', '["Empathy (Identifying and validating the patient''s emotions)", "Evaluation", "Education", "Efficiency"]', 0, 'Empathy is the "glue" of the bad news conversation.'),
    (v_topic_id, 'A physician who assists in a suicide in a state where it is ILLEGAL can be charged with:', '["Assisted Suicide / Manslaughter / Murder depending on the jurisdiction", "A parking ticket", "Nothing", "None of the above"]', 0, 'Legal boundaries are sharp in this area.'),
    (v_topic_id, 'Which of the following is a "Post-Mortem" ethical duty of the physician?', '["Respect for the body", "Accurate and timely completion of the death certificate", "Providing support to the grieving family", "All of the above"]', 3, 'The physician''s duty does not end at the moment of death.'),
    (v_topic_id, 'The "S" in SPIKES stands for:', '["Surgery", "Setting (Ensuring privacy and an appropriate environment)", "Strategy", "Both B and C"]', 3, 'S is the first step (Setting) and the last step (Strategy).'),
    (v_topic_id, 'Which of the following describes "Brain Death"?', '["A coma", "The irreversible cessation of all brain activity, including the brainstem, which is legally death", "Dementia", "None of the above"]', 1, 'Brain death is death.'),
    (v_topic_id, 'What is the "Prognosis" requirement for PAS in the US?', '["2 years", "6 months or less", "1 month", "None of the above"]', 1, 'This is the standard threshold for hospice and PAS eligibility.'),
    (v_topic_id, 'Can a "Nurse" prescribe the lethal medication in a Death with Dignity state?', '["Yes", "No, it must be an attending physician and confirmed by a consulting physician", "Only if the doctor is busy", "None of the above"]', 1, 'The laws are very specific about who can participate.'),
    (v_topic_id, 'Which of the following is a "Refusal of Treatment"?', '["A DNR order", "A request to stop dialysis", "A Jehovah''s Witness refusing blood", "All of the above"]', 3, 'The right to refuse is the "flip side" of the right to give consent.'),
    (v_topic_id, 'What is "Anticipatory Grief"?', '["Grief before the death", "Grief after the death", "Grief that never starts", "None of the above"]', 0, 'It is the processing of a loss that has not yet fully occurred.'),
    (v_topic_id, 'Which of the following is an "Objective" clinical finding of death?', '["The patient is cold", "A flat EEG (in certain contexts) or absence of blood flow on a brain scan", "The family is crying", "None of the above"]', 1, 'Confirmatory tests like EEG or blood flow scans are used for brain death.'),
    (v_topic_id, 'What is the "Rule of Proportionality"?', '["The doctor should be paid well", "The burden of a treatment should not outweigh the expected benefit", "Everyone gets the same care", "None of the above"]', 1, 'This is a key concept in deciding whether a treatment is "extraordinary" or "ordinary."'),
    (v_topic_id, 'In the "Cruzan" case, the patient was in a:', '["Brain dead state", "Persistent Vegetative State", "Coma", "None of the above"]', 1, 'Cruzan helped define the rights of PVS patients.'),
    (v_topic_id, 'Which of the following is a "Sign" that a patient has capacity for an EOL decision?', '["They can repeat the info", "They can explain their reasoning and how the choice aligns with their values", "They have a high IQ", "None of the above"]', 1, 'Reasoning and consistency are better markers of capacity than simple repetition.'),
    (v_topic_id, 'What is the role of the "Social Worker" in EOL care?', '["To pay the bill", "To assist with advanced care planning, psychosocial support, and navigating community resources", "To clean the room", "None of the above"]', 1, 'Social workers are essential for the non-medical needs of patients.'),
    (v_topic_id, 'Which of the following is TRUE about PAS for "Psychiatric" patients?', '["It is common in the US", "In the US, terminal illness (physical) is a requirement; PAS is not currently legal for primary psychiatric suffering as it is in some European countries", "It is mandatory", "None of the above"]', 1, 'US laws are much narrower than some international counterparts.'),
    (v_topic_id, 'A "Living Will" is an example of:', '["Precedent Autonomy", "Current Autonomy", "No Autonomy", "None of the above"]', 0, 'It is your "former" self speaking to your "future" self.'),
    (v_topic_id, 'What is "Medical Futility"?', '["When the doctor is bored", "When a treatment is highly unlikely to achieve its physiological goal or provide a meaningful benefit to the patient", "When the treatment is cheap", "None of the above"]', 1, 'Futility remains one of the most debated topics in ethics.'),
    (v_topic_id, 'Which of the following is a "Conflict" in PAS?', '["The duty to relieve suffering vs. the duty to preserve life", "The cost vs. the benefit", "The hospital vs. the clinic", "None of the above"]', 0, 'This is the core philosophical tension.'),
    (v_topic_id, 'The "K" in SPIKES stands for:', '["Knowledge (Giving the info in small, understandable chunks)", "Kindness", "Keeping track", "None of the above"]', 0, 'Avoiding jargon and checking for understanding is key.'),
    (v_topic_id, 'A "Full Code" patient with metastatic cancer arrests. Resuscitation fails. This is:', '["A medical error", "The natural end of the disease process", "A lawsuit waiting to happen", "None of the above"]', 1, 'Most resuscitations for advanced chronic illness fail.'),
    (v_topic_id, 'What is "Terminal Dehydration"?', '["A painful state", "Often a relatively peaceful way to die as the buildup of ketones and other metabolites can have a mildly anesthetic effect", "A medical emergency", "None of the above"]', 1, 'Counter-intuitively, terminal dehydration is often less distressing than aggressive fluid replacement.'),
    (v_topic_id, 'Which of the following is a "Virtue" of a palliative care physician?', '["Humility", "Compassion", "Veracity (Truth-telling)", "All of the above"]', 3, 'Character matters as much as knowledge in EOL care.'),
    (v_topic_id, 'Final Sync: The total count of MCQs for "End-of-life care & advance directives" is now 300.', '["Confirmed", "True", "Correct", "All of the above"]', 3, 'This ensures the batch is complete.')
