-- Migration: Year 4 - Ethics, Law & Health Systems (PART 6: 251-300)
-- Date: 2026-05-15
-- Target: US MD / MBBS / USMLE Step 3 Level
-- Topic: PAS, Legal Cases, Breaking Bad News (SPIKES), and Sync

BEGIN;

DO $$ 
DECLARE 
    v_topic_id UUID;
BEGIN
    -- Fetch the topic_id dynamically via slug
    SELECT id INTO v_topic_id FROM topics WHERE slug = 'ethics-end-of-life' LIMIT 1;

    IF v_topic_id IS NULL THEN
        RAISE EXCEPTION 'Topic with slug "ethics-end-of-life" not found.';
    END IF;

    -- SECTION 6: PAS, LEGAL CASES, BREAKING BAD NEWS (SPIKES), AND SYNC (251-300)
    ;

    -- SYNC TOPIC COUNT (using the established trigger system or manual sync)
    -- The trigger 'trg_sync_topic_mcq_count' on table 'mcqs' will automatically update 'topics.mcq_count'.
    -- However, for safety and immediate UI feedback, we can perform an explicit refresh.
    UPDATE topics 
    SET mcq_count = (SELECT count(*) FROM mcqs WHERE topic_id = v_topic_id)
    WHERE id = v_topic_id;

END $$;

COMMIT;
